WITH selected AS MATERIALIZED (SELECT level.id,level.xx_hash FROM public.level level JOIN LATERAL (SELECT source.* FROM public.level_item source WHERE source.id_level=level.id AND source.deleted=false ORDER BY source.updated_at DESC,source.id DESC LIMIT 1) item ON true LEFT JOIN public."user" author ON author.steam_id=item.author_id WHERE level.publicly_visible=true AND (level.xx_hash ILIKE $1 OR level.id::text=$1 OR item.name ILIKE '%'||$1||'%' OR author.steam_name ILIKE '%'||$1||'%') ORDER BY (level.xx_hash=$1) DESC,(level.id::text=$1) DESC,(lower(item.name)=lower($1)) DESC, similarity(item.name,$1) DESC,level.id DESC LIMIT 1) SELECT jsonb_build_object('id',level.id,'xxHash',level.xx_hash,'name',item.name, 'imageUrl',item.image_url,'workshopId',item.workshop_id::text,'authorName',author.steam_name, 'authorDiscordId',author.discord_id::text,'points',COALESCE(points.points,0), 'rating',COALESCE(points.rating,0),'records',(SELECT count(*) FROM (SELECT * FROM public.record WHERE record_eligible) r WHERE r.id_level=level.id), 'personalBests',(SELECT count(*) FROM (SELECT * FROM public.personal_best_global WHERE record_eligible) pb WHERE pb.id_level=level.id), 'votes',(SELECT count(*) FROM public.vote vote WHERE vote.id_level=level.id), 'worldRecord',CASE WHEN wr.id IS NULL THEN NULL ELSE jsonb_build_object('time',wr_record.time, 'steamName',wr_user.steam_name,'discordId',wr_user.discord_id::text) END, 'leaderboard',COALESCE((SELECT jsonb_agg(jsonb_build_object('rank',ranked.rank, 'time',ranked.time,'steamName',ranked.steam_name,'discordId',ranked.discord_id::text) ORDER BY ranked.rank) FROM (SELECT row_number() OVER(ORDER BY record.time,record.id) AS rank, record.time,account.steam_name,account.discord_id FROM (SELECT * FROM public.personal_best_global WHERE record_eligible) pb JOIN (SELECT * FROM public.record WHERE record_eligible) record ON record.id=pb.id_record JOIN public."user" account ON account.id=pb.id_user WHERE pb.id_level=level.id ORDER BY record.time,record.id LIMIT 10) ranked),'[]'::jsonb)) AS value FROM selected JOIN public.level level USING(id) JOIN LATERAL (SELECT source.* FROM public.level_item source WHERE source.id_level=level.id AND source.deleted=false ORDER BY source.updated_at DESC,source.id DESC LIMIT 1) item ON true LEFT JOIN public."user" author ON author.steam_id=item.author_id LEFT JOIN public.level_points points ON points.id_level=level.id LEFT JOIN (SELECT * FROM public.world_record_global WHERE record_eligible) wr ON wr.id_level=level.id LEFT JOIN (SELECT * FROM public.record WHERE record_eligible) wr_record ON wr_record.id=wr.id_record LEFT JOIN public."user" wr_user ON wr_user.id=wr.id_user
